select t.slug, count(q.id) filter (where q.statement_id is not null) as linked, count(q.id) filter (where q.statement_id is not null and q.difficulty='exam') as linked_exam, count(q.id) as all_qs from topics t join subject_levels sl on sl.id=t.subject_level_id join subjects s on s.id=sl.subject_id join quizzes z on z.topic_id=t.id join questions q on q.quiz_id=z.id where s.name ilike '%physics%' and sl.level::text='A2' group by t.slug order by t.slug;
